import heapq


def _dijkstra(adj, s, n):
    INF = float('inf')
    dis = [INF] * n
    dis[s] = 0
    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dis[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dis[v]:
                dis[v] = nd
                heapq.heappush(pq, (nd, v))
    return dis


def johnson(n, edges):
    """全源最短路(支持负权, 无负环). edges: [(u,v,w)].
    返回 dis 矩阵; 不可达为 float('inf'); 存在负环返回 None."""
    INF = float('inf')
    super_src = n
    super_edges = edges + [(super_src, i, 0) for i in range(n)]

    h = [INF] * (n + 1)
    h[super_src] = 0
    for _ in range(n):
        updated = False
        for u, v, w in super_edges:
            if h[u] != INF and h[u] + w < h[v]:
                h[v] = h[u] + w
                updated = True
        if not updated:
            break
    for u, v, w in super_edges:
        if h[u] != INF and h[u] + w < h[v]:
            return None  # 负环

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        w2 = w + h[u] - h[v]
        if w2 < 0:
            w2 = 0  # 数值保护(理论上 w'>=0, 浮点/取整边界兜底)
        adj[u].append((v, w2))

    ans = [[INF] * n for _ in range(n)]
    for s in range(n):
        d2 = _dijkstra(adj, s, n)
        for t in range(n):
            if d2[t] != INF:
                ans[s][t] = d2[t] - h[s] + h[t]
            else:
                ans[s][t] = INF
    return ans


if __name__ == "__main__":
    # 带负权的稀疏图
    n = 4
    edges = [(0, 1, 3), (0, 2, -2), (1, 3, 2), (2, 3, 5), (2, 1, 1), (3, 1, -1)]
    ans = johnson(n, edges)
    assert ans is not None
    assert ans[0][3] == 1, ans[0]  # 0->2(-2)->1(1)->3(2) = 1
    assert ans[0] == [0, -1, -2, 1], ans[0]

    # 与 Floyd 交叉验证
    import random
    random.seed(41)
    for _ in range(200):
        n = random.randint(1, 7)
        edges = []
        for i in range(n):
            for j in range(n):
                if i != j and random.random() < 0.3:
                    edges.append((i, j, random.randint(-4, 7)))
        # Floyd 参考
        INF = float('inf')
        d = [[INF] * n for _ in range(n)]
        for i in range(n):
            d[i][i] = 0
        for u, v, w in edges:
            d[u][v] = min(d[u][v], w)
        for k in range(n):
            for i in range(n):
                if d[i][k] == INF:
                    continue
                for j in range(n):
                    if d[k][j] == INF:
                        continue
                    d[i][j] = min(d[i][j], d[i][k] + d[k][j])
        neg = any(d[i][i] < 0 for i in range(n))
        ans = johnson(n, edges)
        if neg:
            assert ans is None, (n, edges)
        else:
            assert ans is not None
            for i in range(n):
                for j in range(n):
                    a, b = ans[i][j], d[i][j]
                    if a == INF or b == INF:
                        assert a == b, (i, j, a, b)
                    else:
                        assert abs(a - b) < 1e-9, (i, j, a, b)

    # 负环
    assert johnson(3, [(0, 1, 1), (1, 2, -3), (2, 0, 1)]) is None
    print("All tests passed.")
